#include <Hibernation/RoleDirection.h>
#include <Hibernation/ReactionCache.h>
#include <Hibernation/SpeechStyle.h>
#include <Hibernation/ModelJson.h>
#include <Hibernation/CacheContext.h>
#include <Hibernation/Review.h>
#include <Hibernation/TextPlayback.h>
#include <AYSerializer/JsonSchema.h>
#include <set>
namespace hibernation {
std::string reactionSchema(){return R"({"type":"object","additionalProperties":false,"required":["version","reactions"],"properties":{"version":{"enum":[1]},"reactions":{"type":"array","maxItems":6,"items":{"type":"object","additionalProperties":false,"required":["text","animation"],"properties":{"text":{"type":"string","minLength":1,"maxLength":160},"animation":{"enum":["curious","idle","resting"]}}}}}})";}
ValidatedOutput validateReactions(std::string_view text){const auto envelope=modelJsonEnvelope(text);if(!envelope)return {false,"reaction_format",{}};const std::string value(*envelope);if(!ayt::serializer::validateJsonDocument(value,reactionSchema()))return {false,"reaction_format",{}};auto parsed=Json::parse(value);std::set<std::string> unique;for(const auto& reaction:parsed.at("reactions")){const auto text=reaction.at("text").get<std::string>();if(text.find('\0')!=std::string::npos||text.find_first_of("\r\n")!=std::string::npos||textOffsets(text).size()>41||!unique.insert(text).second)return {false,"reaction_text",{}};}return {true,"ok",std::move(parsed)};}
ReactionGenerator::~ReactionGenerator(){stop();}
bool ReactionGenerator::running()const{return future_.valid();}
void ReactionGenerator::cancel(){if(cancelled_)cancelled_->store(true);}
void ReactionGenerator::stop(){cancel();if(future_.valid()){future_.wait();try{future_.get();}catch(...){}}}
std::optional<ReactionBatch> ReactionGenerator::poll(){if(!future_.valid()||future_.wait_for(std::chrono::milliseconds(0))!=std::future_status::ready)return {};return future_.get();}
void ReactionGenerator::start(Profile actor,std::optional<Profile> reviewer,Json persona,Json state,Json excluded,std::string key,std::function<bool()> reserveCall,std::function<void(const Profile&,int)> observeResult,std::function<void(const Profile&,const std::string&,const ayt::inference::Usage&)> observeUsage){if(running())return;cancelled_=std::make_shared<std::atomic<bool>>(false);auto cancel=cancelled_;
    future_=std::async(std::launch::async,[actor=std::move(actor),reviewer=std::move(reviewer),persona=std::move(persona),state=std::move(state),excluded=std::move(excluded),key=std::move(key),cancel,reserveCall=std::move(reserveCall),observeResult=std::move(observeResult),observeUsage=std::move(observeUsage)]()mutable{ReactionBatch batch;batch.key=key;try{
        const auto started=std::chrono::steady_clock::now();ayt::inference::Request request;request.cancelled=[cancel]{return cancel->load();};request.maxOutputTokens=actor.maxOutputTokens;batch.usage["actor_max_output_tokens"]=request.maxOutputTokens;request.schemaName="interaction_reactions_v1";if(actor.model.supportsJsonSchema||actor.model.supportsJsonObject)request.outputSchema=reactionSchema();
        request.messages={{"system","你正在为虚拟角色预先准备将来可能使用的短反应，不是在进行当下交谈。只输出给定 JSON，不输出思维链或工具调用。为角色被鼠标轻轻挪动这一常见动作准备最多六条独立、简短、自然且各不相同的反应，每条最多40字。用自身语气，可以不满、玩笑、安静或拒绝，不固定问用户为什么拖动。不能假定方向、次数、距离、痛苦、恋爱关系或用户意图，不能提及缓存、测试、管理程序，不能声称未来动作已经发生。不要把拖动变成当前故事或技术排障话题；不能宣讲人格规则。可以返回空数组表示没有合适反应。已使用或已缓存的原句不能重复。人格："+rolePersona(persona).dump()+"\n"+dialogueDeliveryConduct()+"\n"+speechStyle::conduct()+"\n格式："+reactionSchema()},{"user",cacheOrderedBackground(Json{{"state",state},{"conversation_delivery",dialogueDeliveryContext()},{"excluded",excluded}})}};
        actor.model.timeout=std::min(actor.model.timeout,std::chrono::milliseconds(20000));ayt::inference::Result result;
        if(actor.model.protocol==ayt::inference::Protocol::Mock){result.text=Json{{"version",1},{"reactions",Json::array({{{"text","脚下的位置换了。"},{"animation","curious"}},{{"text","嗯，这里也可以。"},{"animation","idle"}},{{"text","让我自己站一会儿。"},{"animation","resting"}},{{"text","刚才那一步不算我走的。"},{"animation","curious"}},{{"text","这次落脚挺稳。"},{"animation","idle"}},{{"text","先停在这里吧。"},{"animation","resting"}}})}}.dump();}
        else{if(cancel->load()){batch.status="cancelled";return batch;}if(reserveCall&&!reserveCall()){batch.status="model_call_budget";return batch;}batch.usage["actor_calls"]=1;result=ayt::inference::invoke(actor.model,request);if(observeUsage){observeUsage(actor,"actor",result.usage);batch.usage["background_budget_observed"]=true;batch.usage["model_cache_observed"]=true;}if(observeResult)observeResult(actor,result.httpStatus);batchCacheUsage(batch.usage,"actor",actor.id,result.usage);if(!result){batch.status=cancel->load()?"cancelled":result.status==ayt::inference::Status::InvalidOutput?"reaction_format":"reaction_model_unavailable";return batch;}}
        batch.modelMs=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-started).count();batch.proposal=result.text;if(result.usage.inputTokens)batch.usage["actor_input_tokens"]=*result.usage.inputTokens;if(result.usage.outputTokens)batch.usage["actor_output_tokens"]=*result.usage.outputTokens;auto checked=validateReactions(result.text);if(!checked.ok){batch.status=checked.code;return batch;}
        if(reviewer&&actor.model.protocol!=ayt::inference::Protocol::Mock){if(cancel->load()){batch.status="cancelled";return batch;}if(reviewer->model.protocol!=ayt::inference::Protocol::Mock&&reserveCall&&!reserveCall()){batch.status="model_call_budget";return batch;}batch.usage["review_calls"]=reviewer->model.protocol==ayt::inference::Protocol::Mock?0:1;ayt::inference::Request review;review.cancelled=request.cancelled;review.maxOutputTokens=reviewer->maxOutputTokens;batch.usage["review_max_output_tokens"]=review.maxOutputTokens;review.schemaName="reaction_review_v1";if(reviewer->model.supportsJsonSchema||reviewer->model.supportsJsonObject)review.outputSchema=reviewSchema();review.messages={{"system",role_direction::activityConduct()+"本次是以后在实际鼠标互动时消耗的一批短反应，重点看角色语气、连续状态与多样性，不要求每条做原则说明。"+rolePersona(persona).dump()+"\n"+dialogueDeliveryConduct()+"\n"+speechStyle::conduct()+"\n格式："+reviewSchema()},{"user",cacheOrderedReview(Json{{"state",state},{"candidate",checked.value},{"excluded",excluded}})}};reviewer->model.timeout=std::min(reviewer->model.timeout,std::chrono::milliseconds(10000));const auto before=std::chrono::steady_clock::now();auto verdict=ayt::inference::invoke(reviewer->model,review);if(reviewer->model.protocol!=ayt::inference::Protocol::Mock&&observeUsage){observeUsage(*reviewer,"review",verdict.usage);batch.usage["background_budget_observed"]=true;batch.usage["model_cache_observed"]=true;}if(reviewer->model.protocol!=ayt::inference::Protocol::Mock)batchCacheUsage(batch.usage,"review",reviewer->id,verdict.usage);if(observeResult)observeResult(*reviewer,verdict.httpStatus);if(verdict.usage.inputTokens)batch.usage["review_input_tokens"]=*verdict.usage.inputTokens;if(verdict.usage.outputTokens)batch.usage["review_output_tokens"]=*verdict.usage.outputTokens;batch.reviewMs=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-before).count();auto valid=verdict?validateReview(verdict.text):ValidatedOutput{};batch.review=valid.ok?valid.value:Json(nullptr);if(!valid.ok||valid.value.at("decision")!="approve"){batch.status=cancel->load()?"cancelled":"reaction_review_rejected";return batch;}}
        if(cancel->load()){batch.status="cancelled";return batch;}for(const auto& item:checked.value.at("reactions"))if(std::find(excluded.begin(),excluded.end(),item.at("text"))==excluded.end())batch.entries.push_back(item);batch.status="ok";
    }catch(...){batch.status=cancel->load()?"cancelled":"reaction_generation_failed";}return batch;});
}
Json takeReaction(Json& pool,std::int64_t now){auto& entries=pool["entries"];for(auto it=entries.begin();it!=entries.end();)if(it->value("expires",std::int64_t(0))<=now)it=entries.erase(it);else ++it;for(auto it=entries.begin();it!=entries.end();++it)if(it->value("ready",false)){auto result=*it;entries.erase(it);pool["used"].push_back(result.at("text"));while(pool["used"].size()>64)pool["used"].erase(0);return result;}return nullptr;}
}

